import math

def is_power_of_five(n):
    if n <= 0:
        return False
    # Check if n is divisible by 5 repeatedly
    if n == 1:
        # 4^z + 1 = 1 implies 4^z = 0, impossible for positive z.
        return False
    temp = n
    while temp > 1:
        if temp % 5 != 0:
            return False
        temp //= 5
    return True

solutions = []
for z in range(1, 100):
    N = 4**z + 1
    if is_power_of_five(N):
        # Find k such that 5^k = N
        k = round(math.log5(N))
        if 5**k == N:
            solutions.append((z, k))

print("Solutions (z, k) such that 4^z + 1 = 5^k for z < 100:")
print(solutions)

import math

def check_factors(n):
    """
    Checks if n is of the form 2^a * 3^b and returns (a, b) if true, or None otherwise.
    Assumes n >= 1.
    """
    if n == 1:
        return (0, 0)

    a = 0
    b = 0
    temp = n

    while temp > 0 and temp % 2 == 0:
        a += 1
        temp //= 2

    while temp > 0 and temp % 3 == 0:
        b += 1
        temp //= 3

    if temp == 1:
        return (a, b)
    else:
        return None

def solve_x5():
    results = []
    for z in range(1, 100):
        N = 5**z + 1
        factors = check_factors(N)

        if factors:
            a, b = factors
            y_min = max(a, b)

            # y must satisfy y_min <= y <= 99. Since y must be positive, 
            # and y_min >= 1 (since 5^z+1 > 1 for z >= 1), this is fine.
            count_y = 99 - y_min + 1

            results.append({
                'z': z,
                'N': N,
                'a': a,
                'b': b,
                'y_min': y_min,
                'count': count_y
            })
    return results

results = solve_x5()
print(results)

import math

def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

def check_z(z):
    # Check if 7^z + 1 is a power of 2
    value = 7**z + 1
    return is_power_of_two(value), value

# Check z from 1 to 99
solutions_z = []
for z in range(1, 100):
    is_pow2, value = check_z(z)
    if is_pow2:
        solutions_z.append(z)
        print(f"z={z}: 7^{z} + 1 = {value} (Power of 2)")

print(f"Number of z values found: {len(solutions_z)}")
